.campo-wrap{display:flex;align-items:center;gap:10px;border:1px solid var(--borda-in);border-radius:10px;padding:0 12px;background:var(--sup);min-height:44px}
.campo-wrap:focus-within{outline:2px solid var(--roxo)}
.campo-wrap input{border:0;outline:0;padding:11px 0;flex:1;min-height:0;background:transparent}
.campo-wrap input:focus{outline:0}
.campo-wrap svg{color:var(--tx3);flex:none}
.campo-wrap .prefixo{color:var(--tx3);font-weight:600}
.campo-wrap input.dinheiro{text-align:right;font-size:16px;font-weight:700;padding-left:8px}
.campo-wrap a,.campo-wrap button.link{font-size:13px;font-weight:700;white-space:nowrap;padding:0;min-height:0}
.seg{display:flex;border:1px solid var(--borda-in);border-radius:10px;overflow:hidden;background:var(--sup)}
.seg button{flex:1;border:0;border-left:1px solid var(--borda-in);padding:11px 0;font-size:14px;font-weight:600;background:var(--sup);color:var(--tx2);min-height:44px}
.seg button:first-child{border-left:0}
.seg button[aria-pressed="true"]{background:var(--roxo);color:#fff;font-weight:700}
.seg.solto{border:0;background:none;gap:8px;flex-wrap:wrap;overflow:visible}
.seg.solto button{flex:0 1 auto;border:1px solid var(--borda-in);border-radius:10px;padding:11px 16px}
.seg.solto button[aria-pressed="true"]{border-color:var(--roxo)}
.check{display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--tx2);font-weight:400}
.check input{width:18px;height:18px;min-height:0;margin-top:2px;accent-color:var(--roxo);flex:none}
.check.forte{font-weight:700;color:var(--tx)}
.check.forte input{width:20px;height:20px}
.rodape{position:sticky;bottom:var(--tabbar);margin-top:auto;background:var(--sup);border-top:1px solid var(--borda);padding:14px 32px;display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:flex-end;box-shadow:0 -8px 24px rgba(84,48,96,.06);z-index:4}
.rodape .nota{font-size:13px;color:var(--tx3);flex:1 1 200px}
.cartoes{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.cardmod{display:flex;flex-direction:column;gap:4px;border:1px solid var(--borda-in);background:var(--sup);border-radius:12px;padding:12px 14px;cursor:pointer;font-weight:400;color:var(--tx2);font-size:13px}
.cardmod .nome{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.cardmod .nome strong{font-size:14px;color:var(--tx)}
.cardmod input{width:18px;height:18px;min-height:0;accent-color:var(--roxo);margin:0;flex:none}
.cardmod.on{border:2px solid var(--roxo);background:#F8F5FA;padding:11px 13px}
.cardmod.antigo{border:1px dashed var(--lilas-b);background:#FBF9FC}
.cardmod.trancado{background:var(--bg);border:1px solid var(--borda);cursor:default;gap:6px}
.cardmod.trancado .nome{font-weight:700}
.cardmod.desab{opacity:.55;cursor:not-allowed}
/* ---------- lista do dia ---------- */
.linha{display:flex;flex-wrap:wrap;align-items:center;gap:12px 18px;background:var(--sup);border:1px solid var(--borda);border-radius:14px;padding:14px 18px;position:relative}
.linha .hora{width:56px;font-family:var(--fh);font-weight:600;font-size:18px;color:var(--tx)}
.linha .quem{flex:1 1 170px;min-width:0}
.linha .quem .nome{font-weight:700;font-size:16px}
.linha .quem .sub{font-size:13px;color:var(--tx3)}
.linha .tags{flex:1 1 150px;display:flex;flex-wrap:wrap;gap:6px}
.linha .acao{display:flex;align-items:center;gap:8px;margin-left:auto}
.linha.destaque{border:2px solid var(--roxo);box-shadow:var(--sombra);padding:13px 17px}
.linha.apagada{opacity:.75}
.linha.fora .nome{text-decoration:line-through;color:var(--tx3)}
.linha.fora .hora{color:var(--tx3)}
.linha .detalhe{flex-basis:100%;font-size:13px;color:var(--tx3);border-top:1px solid var(--borda-leve);padding-top:10px}
.mais{position:relative}
.mais-menu{position:absolute;right:0;top:calc(100% + 6px);background:var(--sup);border:1px solid var(--borda);border-radius:12px;box-shadow:var(--sombra-forte);padding:6px;min-width:220px;z-index:6;display:flex;flex-direction:column}
.mais-menu button{border:0;background:none;text-align:left;padding:10px 12px;border-radius:8px;font-size:14px;font-weight:600;color:var(--tx2);min-height:40px}
.mais-menu button:hover{background:var(--bg);color:var(--roxo)}
.mais-menu button.perigo{color:var(--vm-tx)}
.lista{display:flex;flex-direction:column;gap:10px}
.painel{background:var(--sup);border:2px solid var(--roxo);border-radius:16px;padding:20px 22px;display:flex;flex-direction:column;gap:14px;box-shadow:var(--sombra-forte)}
.painel .cab{display:flex;flex-wrap:wrap;align-items:center;gap:10px}
.fim-dia .check{font-size:14px}
/* ---------- tabelas ---------- */
.tabela-card{background:var(--sup);border:1px solid var(--borda);border-radius:16px;overflow:hidden}
.tabela-wrap{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:14px;min-width:720px}
thead tr{background:#F8F5FA;color:var(--tx3);font-size:12px;text-transform:uppercase;letter-spacing:.06em}
th{text-align:left;padding:12px;font-weight:700;white-space:nowrap}
th:first-child,td:first-child{padding-left:18px}
th:last-child,td:last-child{padding-right:18px}
th.num,td.num{text-align:right}
td{padding:14px 12px;vertical-align:middle;border-top:1px solid var(--borda-leve)}
td .sub{font-size:12px;color:var(--tx3)}
tr.atrasada td{background:var(--vm-linha)}
tr.apagada td{color:var(--tx3)}
.tabela-rodape{padding:12px 18px;border-top:1px solid var(--borda-leve);font-size:13px;color:var(--tx3);display:flex;flex-wrap:wrap;gap:8px 20px}
/* ---------- kpis e pendências (mensalistas, gestão) ---------- */
.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}
.kpi{text-align:left;background:var(--sup);border:1px solid var(--borda);border-radius:14px;padding:16px 18px;display:flex;flex-direction:column;gap:2px;color:var(--tx)}
.kpi b{font-family:var(--fh);font-weight:600;font-size:28px;line-height:1.1}
.kpi span{font-size:13px;color:var(--tx3)}
button.kpi{cursor:pointer}
button.kpi[aria-pressed="true"],.kpi.roxo{background:var(--roxo);color:#fff;border-color:var(--roxo)}
button.kpi[aria-pressed="true"] span,.kpi.roxo span{color:#fff;opacity:.9}
.kpi.verde b{color:var(--vd-tx)}.kpi.amarela b{color:var(--am-tx)}.kpi.vermelha b{color:var(--vm-tx)}
.kpi.amarela.cheio{background:var(--am-bg);border-color:var(--am-bg)}.kpi.amarela.cheio span{color:var(--am-tx)}
.kpi.pessego{background:var(--pessego);border-color:var(--pessego)}.kpi.pessego b{color:var(--roxo-h)}.kpi.pessego span{color:var(--pessego-tx)}
.pend{display:flex;flex-wrap:wrap;align-items:center;gap:14px;background:var(--sup);border:1px solid var(--borda);border-left:6px solid var(--borda);border-radius:14px;padding:14px 18px;text-align:left;color:inherit;width:100%;font:inherit}
.pend:hover{background:#FBF9FC}
.pend[aria-expanded="true"]{box-shadow:var(--sombra)}
.pend .n{font-family:var(--fh);font-weight:600;font-size:24px;min-width:40px}
.pend .corpo{flex:1 1 260px}
.pend .corpo b{display:block;font-weight:700}
.pend .corpo span{font-size:13px;color:var(--tx3)}
.pend .ver{font-size:13px;font-weight:700;color:var(--roxo);display:flex;align-items:center;gap:4px}
.pend.amarela{border-left-color:var(--am-b)}.pend.amarela .n{color:var(--am-tx)}
.pend.laranja{border-left-color:var(--lar-b)}.pend.laranja .n{color:var(--lar-tx)}
.pend.lilas{border-left-color:var(--lilas-med)}.pend.lilas .n{color:var(--roxo)}
.pend.vermelha{border-left-color:var(--vm-b)}.pend.vermelha .n{color:var(--vm-tx)}
.pend.verde .n{color:var(--vd-tx)}
.discreto{display:flex;flex-wrap:wrap;gap:8px 20px;font-size:13px;color:var(--tx3);padding:4px 18px}
.discreto button{border:0;background:none;color:var(--tx3);font-size:13px;padding:0;text-decoration:underline dotted}
.discreto button:hover{color:var(--roxo)}
.virada{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:8px;font-size:14px;color:var(--tx2);line-height:1.6}
.virada li{display:flex;gap:10px;align-items:flex-start}
.virada .ok,.virada .falta{width:22px;height:22px;border-radius:999px;flex:none;margin-top:1px;display:flex;align-items:center;justify-content:center}
.virada .ok{background:var(--vd-bg);color:var(--vd-tx)}
.virada .falta{border:2px solid var(--borda-in)}
.atalho{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:14px;font-weight:700;padding:10px 12px;border-radius:10px;background:var(--bg);color:var(--roxo);text-decoration:none;border:0;width:100%;text-align:left;font-family:inherit}
.atalho small{font-size:12px;color:var(--tx3);font-weight:400}
.atalho .cont{font-size:12px;color:var(--lar-tx);background:var(--lar-bg);border-radius:999px;padding:2px 8px}
/* ---------- toast ---------- */
.toast{position:fixed;left:50%;bottom:calc(18px + var(--tabbar));transform:translateX(-50%);background:var(--roxo-h);color:#fff;padding:10px 18px;border-radius:999px;font-weight:600;opacity:0;transition:opacity .25s;pointer-events:none;box-shadow:var(--sombra);max-width:90vw;text-align:center;z-index:9}
.toast.show{opacity:1}
/* ---------- barra inferior (celular) ---------- */
.tabbar{display:none}
